code_sketch:
thread_local std::vector<char> scratch;   // one buffer per thread, no locks

void handle(Request& r) {                  // runs on exactly one worker thread
    scratch.clear();
    encode(r, scratch);                    // scratch never crosses a thread
    r.reply(scratch);
}

