static pthread_key_t key;                       // one key per logical slot
static void create_key() { pthread_key_create(&key, &parser_close); }
pthread_once(&once, &create_key);               // key init must be serialized
Parser* p = static_cast<Parser*>(pthread_getspecific(key));
if (!p) { p = new Parser(); pthread_setspecific(key, p); }
